function r = lookup_linear(T, x)
%LOOKUP_LINEAR  straight-line between the two rows around x, held at the ends.
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    n = size(T, 1);
    xc = asils.pc.clamp(x, T(1, 1), T(n, 1));
    i = 1;
    while i + 2 <= n && T(i + 1, 1) <= xc, i = i + 1; end
    s = (xc - T(i, 1))/(T(i + 1, 1) - T(i, 1));
    r = T(i, :);
    for j = 1:size(T, 2), r(j) = T(i, j) + s*(T(i + 1, j) - T(i, j)); end
end
